INSERT INTO questions (id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, source_crop, text_checked, formula_checked, solution_checked, unresolved_ocr_items, katex_errors, reviewed_at, status, created_at, updated_at, paper_id, reviewed_by_id) VALUES ('118', '2', '2', 'calculation', '8', '设 \(f(t)\) 在 \(t\ne0\) 时一阶连续可导，且 \(f(1)=0\)。求 \(f(x^2-y^2)\)，使
