INSERT INTO questions (id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, source_crop, text_checked, formula_checked, solution_checked, unresolved_ocr_items, katex_errors, reviewed_at, status, created_at, updated_at, paper_id, reviewed_by_id) VALUES ('141', '5', '5', 'proof', '12', '空间 \(\mathbb R^3\) 中有 2021 个半径非零的球 \(B_i\)。令 \(A=(a_{ij})\)，其中 \(a_{ij}\) 为 \(B_i\cap B_j\) 的体积。证明 \(|E+A|>1\)。', '\(|E+A|>1\)。', '把 \(a_{ij}\) 写成两个球的示性函数内积，得 \(A\) 半正定。其特征值均非负，且 \(A\ne0\)，所以至少一个特征值为正，故 \(|E+A|=\prod(1+\lambda_i)>1\)。', '2021 年第十一届全国大学生数学竞赛决赛（非数学类） 空间 ( R 3 ) 中有 2021 个半径非零的球 (B i )。令 (A=(a ij ) )，其中 (a ij ) 为 (B i B j ) 的体积。证明 (|E+A|>1 )。 (|E+A|>1 )。 把 (a ij ) 写成两个球的示性函数内积，得 (A ) 半正定。其特征值均非负，且 (A 0 )，所以至少一个特征值为正，故 (|E+A|= (1+ i)>1 )。', '1', '', '1', '1', '1', '0', '0', '2026-08-09 03:44:14.082392', 'published', '2026-08-09 03:44:14.083384', '2026-08-09 03:44:14.083384', '22', '1') ON CONFLICT (id) DO NOTHING;
